import React from "react";

// Presentational SVG icons. These are pure and must live at module scope:
// defining a component inside another component creates a new type on every
// render, which unmounts/remounts the subtree and restarts CSS animations.

const iconStroke = {
  fill: "none",
  stroke: "currentColor",
  strokeWidth: 1.9,
  strokeLinecap: "round",
  strokeLinejoin: "round",
};

const ButtonIcon = ({ type, ...props }) => {
  const icons = {
    mic: (
      <svg viewBox="0 0 24 24" className="icon-svg" {...props}>
        <rect x="9" y="3" width="6" height="11" rx="3" {...iconStroke} />
        <path d="M5.5 11.5a6.5 6.5 0 0 0 13 0" {...iconStroke} />
        <path d="M12 18v3" {...iconStroke} />
      </svg>
    ),
    stop: (
      <svg viewBox="0 0 24 24" className="icon-svg" {...props}>
        <rect
          x="6.5"
          y="6.5"
          width="11"
          height="11"
          rx="2.5"
          fill="currentColor"
        />
      </svg>
    ),
    auto: (
      <svg viewBox="0 0 24 24" className="icon-svg" {...props}>
        <path d="M4.5 12a7.5 7.5 0 0 1 12.9-5.2L20 9.2" {...iconStroke} />
        <path d="M20 4.7v4.5h-4.5" {...iconStroke} />
        <path d="M19.5 12a7.5 7.5 0 0 1-12.9 5.2L4 14.8" {...iconStroke} />
        <path d="M4 19.3v-4.5h4.5" {...iconStroke} />
      </svg>
    ),
    test: (
      <svg viewBox="0 0 24 24" className="icon-svg" {...props}>
        <path d="M4 9.5v5h3.2l4.3 3.8V5.7L7.2 9.5H4z" {...iconStroke} />
        <path d="M15 9.3a4 4 0 0 1 0 5.4" {...iconStroke} />
        <path d="M17.8 6.8a7.6 7.6 0 0 1 0 10.4" {...iconStroke} />
      </svg>
    ),
    "3d": (
      <svg viewBox="0 0 24 24" className="icon-svg" {...props}>
        <path
          d="M12 3l7.5 4.3v8.7L12 20.9l-7.5-4.9V7.3L12 3z"
          {...iconStroke}
        />
        <path
          d="M12 12.2l7.5-4.4M12 12.2v8.4M12 12.2L4.5 7.8"
          {...iconStroke}
        />
      </svg>
    ),
    flat: (
      <svg viewBox="0 0 24 24" className="icon-svg" {...props}>
        <rect x="4" y="4" width="16" height="16" rx="3.5" {...iconStroke} />
        <path d="M4 9.5h16" {...iconStroke} />
      </svg>
    ),
    keyboard: (
      <svg viewBox="0 0 24 24" className="icon-svg" {...props}>
        <rect x="2.5" y="6" width="19" height="12" rx="2.5" {...iconStroke} />
        <path
          d="M6 9.5h.01M9.5 9.5h.01M13 9.5h.01M16.5 9.5h.01"
          {...iconStroke}
        />
        <path d="M6 13h.01M9.5 13h.01M13 13h.01M16.5 13h.01" {...iconStroke} />
        <path d="M8.5 15.6h7" {...iconStroke} />
      </svg>
    ),
  };

  return icons[type] || icons.mic;
};

// Avatar glyph — replaces emoji with crisp white SVG marks per state
const AvatarGlyph = ({ state, disabled, isMobile }) => {
  const size = isMobile ? 24 : 36;
  const stroke = {
    fill: "none",
    stroke: "#FFFFFF",
    strokeWidth: 1.8,
    strokeLinecap: "round",
    strokeLinejoin: "round",
  };

  let content;
  if (disabled) {
    content = (
      <>
        <rect x="5.5" y="10.5" width="13" height="9" rx="2.5" {...stroke} />
        <path d="M8.5 10.5V8a3.5 3.5 0 0 1 7 0v2.5" {...stroke} />
        <circle cx="12" cy="15" r="1.4" fill="#FFFFFF" />
      </>
    );
  } else if (state === "listening") {
    content = (
      <>
        <rect x="9" y="3" width="6" height="11" rx="3" {...stroke} />
        <path d="M5.5 11.5a6.5 6.5 0 0 0 13 0" {...stroke} />
        <path d="M12 18v3" {...stroke} />
      </>
    );
  } else if (state === "thinking") {
    content = (
      <>
        <path
          d="M12 3.5l1.8 5.2 5.2 1.8-5.2 1.8L12 17.5l-1.8-5.2L5 10.5l5.2-1.8L12 3.5z"
          fill="#FFFFFF"
          fillOpacity="0.92"
        />
        <circle cx="18.5" cy="17.5" r="1.6" fill="#FFFFFF" fillOpacity="0.75" />
        <circle cx="5.5" cy="18" r="1.1" fill="#FFFFFF" fillOpacity="0.6" />
      </>
    );
  } else if (state === "speaking") {
    content = (
      <>
        <path d="M4 9.5v5h3.2l4.3 3.8V5.7L7.2 9.5H4z" {...stroke} />
        <path d="M15 9.3a4 4 0 0 1 0 5.4" {...stroke} />
        <path d="M17.8 6.8a7.6 7.6 0 0 1 0 10.4" {...stroke} />
      </>
    );
  } else {
    // idle — voice waveform
    content = (
      <path
        d="M4.5 10.5v3M8.25 7.5v9M12 5v14M15.75 7.5v9M19.5 10.5v3"
        {...stroke}
        strokeWidth="2.2"
      />
    );
  }

  return (
    <svg
      width={size}
      height={size}
      viewBox="0 0 24 24"
      style={{ filter: "drop-shadow(0 2px 4px rgba(0, 0, 0, 0.3))" }}
    >
      {content}
    </svg>
  );
};

// Streams text into the transcript with a typing caret. Scroll is kept
