  // ============= TURN PIPELINE =============
  // A "turn" used to be one ~300-line callback with six sequential branches
  // and an `isProcessingRef` that was cleared before the answer had finished
  // speaking. It is now an ordered list of small handlers; each returns true
  // once it has taken the turn. Benefits:
  //   - the precedence order is visible in one place
  //   - a typed message and a spoken utterance travel the identical path
  //   - every branch awaits its speech, so the busy flag is honest

  const handlePendingEmailConfirmation = useCallback(
    async (text) => {
      if (!pendingEmailSendRef.current) return false;

      // Word boundaries matter here: the old substring checks meant "look"
      // contained "ok" and "I don't know" contained "no".
      const affirmative = /\b(yes|yeah|yep|confirm|confirmed|sure|ok|okay|send|send it|go ahead|please do)\b/i.test(
        text
      );
      const negative = /\b(cancel|no|nope|stop|abort|don't|do not|never ?mind)\b/i.test(
        text
      );

      if (affirmative && !negative) {
        setAssistantState("thinking");
        const sendResult = await pendingEmailSendRef.current();
        pendingEmailSendRef.current = null;

        if (sendResult.success) {
          showNotice(
            "success",
            "✅ Email Sent",
            "Laxman will respond soon!",
            3000
          );
        } else {
          showNotice(
            "error",
            "❌ Send Failed",
            "Please try direct email",
            3000
          );
        }

        setAssistantState("speaking");
        await speakResponse(sendResult.response);
        return true;
      }

      if (negative) {
        pendingEmailSendRef.current = null;
        EmailAgent.cancel();
        setAssistantState("speaking");
        await speakResponse(
          "Okay, email cancelled. What else can I help with?"
        );
        return true;
      }

      setAssistantState("speaking");
      await speakResponse("Please say 'yes' to send or 'cancel' to stop.");
      return true;
    },
    [showNotice, speakResponse]
  );

  const handleEmailCollection = useCallback(
    async (text) => {
      if (!EmailAgent.conversationState.isCollecting) return false;

      setAssistantState("thinking");

      if (/\b(cancel|stop|abort|never ?mind)\b/i.test(text)) {
        const result = EmailAgent.cancel();
        setAssistantState("speaking");
        await speakResponse(result.response);
        return true;
      }

      const result = EmailAgent.processAnswer(text);

      // Arm the confirmation BEFORE speaking: speakResponse's end-of-speech
      // handler checks the pending-send ref to decide whether to reopen the
      // mic, and the old code set it after the call.
      if (result.action === "CONFIRM_EMAIL") {
        pendingEmailSendRef.current = result.onConfirm;
      }

      setAssistantState("speaking");
      await speakResponse(result.response);
      return true;
    },
    [speakResponse]
  );

